const escape = value => String(value ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[c]);
let filters = { text: '', namespace: '', scope: 'all', result: 'configured', page: 0 };
const decision = (allow, deny) => allow && deny ? 'Permitir y denegar' : deny ? 'Denegar' : allow ? 'Permitir' : 'Sin establecer';
const stamp = value => new Date(value).toLocaleString('es');
export function resetPermissionFilters() { filters = { text: '', namespace: '', scope: 'all', result: 'configured', page: 0 }; }
export function permissionsView(snapshot, config) {
  const catalog = snapshot?.catalog, report = snapshot?.report;
  return `<section class="permissions-page"><div class="permissions-heading"><div><p class="eyebrow">SEGURIDAD DEL PROYECTO</p><h1>Permisos</h1><p>${escape(config?.project || 'Conecta un proyecto para explorar sus grupos y accesos.')}${catalog ? ` · ${catalog.groups.filter(g => g.scope === 'project').length} grupos del proyecto` : ''}</p></div><div class="workspace-data-actions"><button class="button" data-action="security-back">Volver a planificación</button>${config?.project ? '<button class="button primary" data-action="security-refresh">Actualizar grupos</button>' : '<button class="button primary" data-action="connect">Conectar Azure DevOps</button>'}</div></div>
  ${!catalog ? '<div class="empty-panel"><h2>Un mapa de acceso por grupo</h2><p>Consulta los grupos de Permissions y sigue sus permisos hasta repositorios, ramas, áreas, pipelines y otros recursos. Cada informe incluye sus fuentes y la cobertura de la consulta.</p></div>' : `<div class="permissions-layout"><aside class="permissions-groups" aria-label="Grupos de permisos"><label class="form-field">Buscar grupo<input type="search" id="security-group-search" placeholder="Nombre o ámbito…"></label><label class="form-field">Mostrar<select id="security-group-scope"><option value="project">Grupos del proyecto</option><option value="all" ${report?.group.scope === 'other' ? 'selected' : ''}>Todos los grupos visibles</option></select></label><p class="text-muted">Los otros grupos pueden conceder acceso desde la organización.</p><div id="security-group-list">${catalog.groups.map(g => `<button class="security-group ${report?.group.descriptor === g.descriptor ? 'selected' : ''}" data-action="security-group" data-descriptor="${escape(g.descriptor)}" data-security-group data-scope="${g.scope}" data-search="${escape(`${g.name} ${g.principalName}`.toLowerCase())}" ${g.scope !== 'project' && report?.group.scope !== 'other' ? 'hidden' : ''} ${report?.group.descriptor === g.descriptor ? 'aria-current="true"' : ''}><strong>${escape(g.name)}</strong><small>${escape(g.principalName)}</small>${g.scope !== 'project' ? '<span>Otro ámbito</span>' : ''}</button>`).join('')}</div><p id="security-groups-empty" hidden>No hay grupos que coincidan.</p><small>Consultado: ${escape(stamp(catalog.fetchedAt))}</small>${catalog.coverage.filter(c => c.status !== 'ok').map(c => `<p class="notice">${escape(c.name)}: ${escape(c.message)}</p>`).join('')}</aside><div class="permissions-report" id="security-report">${report ? reportView(report) : '<div class="empty-panel"><h2>Elige un grupo</h2><p>Analizaremos sus permisos directos, los grupos de los que hereda y las asignaciones en los recursos. Podrás seguir el progreso y cancelar la consulta.</p></div>'}</div></div>`}</section>`;
}
function reportView(report) {
  const configured = report.rows.filter(r => r.configured), unresolved = configured.filter(r => r.scope.kind === 'unresolved');
  const failures = report.coverage.filter(c => c.status === 'error');
  return `<div class="permissions-report-heading"><div><h2>${escape(report.group.name)}</h2><p>${escape(report.group.description || report.group.principalName)}</p><small>Consultado: ${escape(stamp(report.completedAt))}</small></div><div class="workspace-data-actions"><button class="button small" data-action="security-group" data-descriptor="${escape(report.group.descriptor)}">Actualizar informe</button><button class="button small" data-action="security-export">Exportar informe</button></div></div>
  <div class="security-stats"><div><strong>${configured.filter(r => r.scope.kind === 'project').length}</strong><span>entradas del proyecto</span></div><div><strong>${report.identities.length - 1}</strong><span>grupos de los que hereda</span></div><div><strong>${report.roles.length}</strong><span>asignaciones de roles</span></div><div><strong>${unresolved.length}</strong><span>entradas sin atribuir</span></div></div>
  <div class="notice"><strong>${failures.length ? `${failures.length} consultas no disponibles.` : 'Consulta de fuentes completada.'}</strong> Las filas muestran concesiones y denegaciones por origen. El acceso final de un usuario puede depender de otras pertenencias y condiciones. <a href="#security-coverage">Ver cobertura</a>.</div>
  <details class="security-details"><summary>Miembros y herencias · ${report.members.length} miembros directos</summary><h3>Miembros directos</h3>${report.members.length ? `<ul>${report.members.map(m => `<li>${escape(m.name)}${m.isContainer ? ' · grupo' : ''}${m.unresolved ? ' · identidad sin resolver' : ''}</li>`).join('')}</ul>` : '<p>Azure no devolvió miembros directos.</p>'}<h3>Grupos de los que hereda</h3><ul>${report.identities.map(i => `<li><strong>${escape(i.name)}</strong>${i.direct ? ' · grupo seleccionado' : ''}<small>${escape(i.descriptor)}</small>${i.memberOf.length ? `<span>Pertenece a: ${i.memberOf.map(d => escape(report.identities.find(p => p.descriptor === d)?.name || d)).join(', ')}</span>` : ''}</li>`).join('')}</ul></details>
  <h3>Permisos por recurso</h3><div class="security-filters"><label class="form-field">Buscar permiso o recurso<input type="search" data-security-filter="text" placeholder="Repositorio, permiso, origen…" value="${escape(filters.text)}"></label><label class="form-field">Ámbito<select data-security-filter="namespace"><option value="">Todos los ámbitos</option>${[...new Set(report.rows.map(r => r.namespace))].sort().map(n => `<option ${n === filters.namespace ? 'selected' : ''}>${escape(n)}</option>`).join('')}</select></label><label class="form-field">Recurso<select data-security-filter="scope"><option value="all">Todos los encontrados</option><option value="project" ${filters.scope === 'project' ? 'selected' : ''}>Del proyecto</option><option value="unresolved" ${filters.scope === 'unresolved' ? 'selected' : ''}>Sin atribuir al proyecto</option></select></label><label class="form-field">Estado<select data-security-filter="result">${Object.entries({ configured: 'Con permiso establecido', deny: 'Con denegaciones', allow: 'Con concesiones', unset: 'Sin establecer en esta entrada', all: 'Todos los permisos de las ACL' }).map(([value, label]) => `<option value="${value}" ${filters.result === value ? 'selected' : ''}>${label}</option>`).join('')}</select></label></div><div id="security-rows">${permissionTable(report)}</div>
  <details class="security-details" ${report.roles.length ? 'open' : ''}><summary>Roles en recursos · ${report.roles.length}</summary>${report.roles.length ? report.roles.map(r => `<div class="security-role"><strong>${escape(r.resource.name)}</strong><span>${escape(typeof r.assignment.role === 'object' ? r.assignment.role.displayName || r.assignment.role.name : r.assignment.role)} · ${escape(r.source)}</span><small>${r.membership === 'direct' ? 'Grupo seleccionado' : 'Por pertenencia a otro grupo'} · ${escape(r.assignment.role?.description || '')}</small><details><summary>Detalle de la asignación</summary><pre>${escape(JSON.stringify(r.assignment, null, 2))}</pre></details></div>`).join('') : '<p>No se encontraron asignaciones para las identidades resueltas en los recursos consultados. Revisa la cobertura antes de interpretar este resultado.</p>'}</details>
  ${report.feedViews.length ? `<details class="security-details"><summary>Visibilidad de las vistas de feeds</summary><p>Estos accesos compartidos pueden ampliar los permisos del feed.</p><ul>${report.feedViews.map(v => `<li>${escape(v.feed)} / ${escape(v.name)} · ${escape(v.visibility)}</li>`).join('')}</ul></details>` : ''}
  <details class="security-details"><summary>Inventario de recursos · ${report.resources.length}</summary><p>Recursos visibles para la cuenta que realizó la consulta. Que un recurso figure aquí no implica que el grupo tenga acceso.</p><ul>${report.resources.map(r => `<li>${escape(r.name)} <small>${escape(r.kind)} · ${escape(r.id)}</small></li>`).join('')}</ul></details>
  <details class="security-details" id="security-coverage" open><summary>Cobertura de la consulta</summary><p>«Consultado» indica que esa fuente respondió. Azure puede filtrar los resultados según tu cuenta. Un permiso sin establecer no significa que el acceso esté denegado.</p>${report.coverage.map(c => `<div class="security-coverage-row"><span class="security-status ${c.status}">${c.status === 'ok' ? 'Consultado' : c.status === 'error' ? 'No disponible' : 'Parcial'}</span><div><strong>${escape(c.name)}</strong>${c.count !== undefined ? ` · ${c.count} resultados` : ''}${c.message ? `<p>${escape(c.message)}</p>` : ''}</div></div>`).join('')}</details>`;
}
function permissionTable(report) {
  const rows = report.rows.filter(r => (!filters.namespace || r.namespace === filters.namespace) && (filters.scope === 'all' || r.scope.kind === filters.scope) && (!filters.text || `${r.permission} ${r.namespace} ${r.token} ${r.scope.label} ${r.source}`.toLowerCase().includes(filters.text.toLowerCase())) && (filters.result === 'all' || filters.result === 'configured' && r.configured || filters.result === 'unset' && !r.configured || filters.result === 'deny' && (r.deny || r.inheritedDeny || r.effectiveDeny) || filters.result === 'allow' && (r.allow || r.inheritedAllow || r.effectiveAllow)));
  const pages = Math.max(1, Math.ceil(rows.length / 100)); filters.page = Math.min(filters.page, pages - 1);
  return `<p role="status">${rows.length} entradas · página ${filters.page + 1} de ${pages}. Una misma acción puede aparecer con varios orígenes.</p>${rows.length ? `<div class="table-wrap"><table class="security-table"><thead><tr><th>Permiso / recurso</th><th>Origen</th><th>Explícito</th><th>Heredado del recurso</th><th>Detalle</th></tr></thead><tbody>${rows.slice(filters.page * 100, filters.page * 100 + 100).map(r => `<tr><td><strong>${escape(r.permission)}</strong><small>${escape(r.namespace)} · ${escape(r.scope.label)}</small><code>${escape(r.token || '(raíz)')}</code></td><td>${escape(r.source)}<small>${r.membership === 'direct' ? 'Grupo seleccionado' : 'Por pertenencia a otro grupo'}</small></td><td><span class="${r.deny ? 'security-deny' : ''}">${decision(r.allow, r.deny)}</span></td><td>${decision(r.inheritedAllow, r.inheritedDeny)}</td><td><details><summary>Ver origen</summary><p>Herencia del recurso: ${r.inheritPermissions === false ? 'bloqueada' : r.inheritPermissions === true ? 'habilitada' : 'no informada'}.</p><p>Resultado comunicado por Azure para esta entrada: ${r.effectiveAllow === null && r.effectiveDeny === null ? 'no informado' : decision(r.effectiveAllow, r.effectiveDeny)}. No combina otras pertenencias del usuario.</p><code>${escape(r.action)} · bit ${r.bit}</code><small>${escape(r.descriptor)}</small></details></td></tr>`).join('')}</tbody></table></div>` : '<div class="empty-panel"><p>No hay entradas que coincidan. Esto no demuestra que el grupo carezca de acceso; revisa roles, herencias y cobertura.</p></div>'}<div class="security-pagination"><button class="button small" data-action="security-page" data-direction="-1" ${filters.page === 0 ? 'disabled' : ''}>Anterior</button><button class="button small" data-action="security-page" data-direction="1" ${filters.page + 1 >= pages ? 'disabled' : ''}>Siguiente</button></div>`;
}
export function filterPermissions(report, name, value) {
  if (name === 'page') filters.page += Number(value); else { filters[name] = value; filters.page = 0; }
  document.querySelector('#security-rows').innerHTML = permissionTable(report);
}
export function filterGroups() {
  const query = document.querySelector('#security-group-search').value.toLowerCase();
  const scope = document.querySelector('#security-group-scope').value;
  let visible = 0;
  document.querySelectorAll('[data-security-group]').forEach(el => { el.hidden = !el.dataset.search.includes(query) || scope !== 'all' && el.dataset.scope !== 'project'; if (!el.hidden) visible++; });
  document.querySelector('#security-groups-empty').hidden = visible !== 0;
}
